#!/usr/bin/env python3
"""Woofmaker — run: python server.py  then open http://localhost:5000"""
from flask import Flask, request, send_file, send_from_directory
import numpy as np
from PIL import Image, ImageDraw
import io, base64

app = Flask(__name__)

QUAD = np.float32([(249,95),(574,5),(727,480),(414,581)])

FACE_POLY = [(244,93),(335,397),(350,393),(348,393),(367,391),(371,406),(380,428),
             (380,426),(391,447),(391,445),(406,466),(426,486),(443,510),(456,529),
             (466,557),(477,579),(520,581),(737,503),(698,363),(678,363),(659,359),
             (659,358),(642,352),(633,333),(639,317),(652,315),(674,300),(581,7)]

FRAMES_DATA = [{"duration": 40, "b64": ""}, {"duration": 50, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 50, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 50, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 50, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 50, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 50, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 50, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}, {"duration": 40, "b64": ""}]

print("Loading frames...", flush=True)
FRAMES = []
for f in FRAMES_DATA:
    img = Image.open(io.BytesIO(base64.b64decode(f["b64"]))).convert("RGB")
    FRAMES.append({"img": img, "duration": f["duration"]})

W, H = FRAMES[-1]["img"].size

_mask_img = Image.new("L", (W, H), 0)
ImageDraw.Draw(_mask_img).polygon(FACE_POLY, fill=255)
FACE_MASK = np.array(_mask_img) > 0
ORIG_OVERLAY = np.array(FRAMES[-1]["img"])

print(f"Ready — {len(FRAMES)} frames. Open http://localhost:5000", flush=True)

def get_homography(src, dst):
    A = []
    for (sx,sy),(dx,dy) in zip(src,dst):
        A.append([-sx,-sy,-1,0,0,0,dx*sx,dx*sy,dx])
        A.append([0,0,0,-sx,-sy,-1,dy*sx,dy*sy,dy])
    A = np.array(A, dtype=np.float64)
    _,_,Vt = np.linalg.svd(A)
    return Vt[-1].reshape(3,3)

def warp_face_onto(bg_img, face_img, zoom=1.0, nudge_x=0, nudge_y=0):
    bg = np.array(bg_img.convert("RGB"), dtype=np.uint8).copy()
    fw, fh = face_img.size

    xs = QUAD[:,0]; ys = QUAD[:,1]
    x0,x1 = int(xs.min()), int(xs.max())
    y0,y1 = int(ys.min()), int(ys.max())
    qw = x1-x0; qh = y1-y0

    base_scale = max(qw/fw, qh/fh) * zoom
    new_fw = int(fw*base_scale); new_fh = int(fh*base_scale)
    scaled = face_img.resize((new_fw, new_fh), Image.LANCZOS)

    paste_x = (qw-new_fw)//2 + int(nudge_x)
    paste_y = (qh-new_fh)//2 + int(nudge_y)
    face_canvas = Image.new("RGB",(qw,qh),(0,0,0))
    sx0=max(0,-paste_x); sy0=max(0,-paste_y)
    sx1=min(new_fw,qw-paste_x); sy1=min(new_fh,qh-paste_y)
    dx0=max(0,paste_x); dy0=max(0,paste_y)
    if sx1>sx0 and sy1>sy0:
        face_canvas.paste(scaled.crop((sx0,sy0,sx1,sy1)),(dx0,dy0))
    face_arr = np.array(face_canvas, dtype=np.uint8)

    src_pts = np.float32([[0,0],[qw,0],[qw,qh],[0,qh]])
    H_mat = get_homography(src_pts, QUAD)
    H_inv = np.linalg.inv(H_mat)

    gx2,gy2 = np.meshgrid(np.arange(x0,x1), np.arange(y0,y1))
    gx2f = gx2.flatten().astype(np.float64)
    gy2f = gy2.flatten().astype(np.float64)
    pts_h = np.stack([gx2f, gy2f, np.ones_like(gx2f)])
    src_h = H_inv @ pts_h
    sx = src_h[0]/src_h[2]; sy = src_h[1]/src_h[2]

    flat_idx = (gy2f.astype(int)*W + gx2f.astype(int))
    in_face = FACE_MASK.flatten()[flat_idx]
    valid = in_face & (sx>=0)&(sx<qw)&(sy>=0)&(sy<qh)

    dx = gx2f[valid].astype(int)
    dy = gy2f[valid].astype(int)
    sxi = np.clip(sx[valid].astype(int),0,qw-1)
    syi = np.clip(sy[valid].astype(int),0,qh-1)
    bg[dy, dx] = face_arr[syi, sxi]

    bg[~FACE_MASK] = ORIG_OVERLAY[~FACE_MASK]

    return Image.fromarray(bg)

@app.route("/")
def index():
    return send_from_directory(".", "woofmaker.html")

@app.route("/preview", methods=["POST"])
def preview():
    face    = Image.open(request.files["photo"].stream).convert("RGB")
    zoom    = float(request.form.get("zoom", 1.0))
    nudge_x = int(float(request.form.get("nudge_x", 0)))
    nudge_y = int(float(request.form.get("nudge_y", 0)))
    result  = warp_face_onto(FRAMES[-1]["img"], face, zoom, nudge_x, nudge_y)
    buf = io.BytesIO(); result.save(buf, format="JPEG", quality=88); buf.seek(0)
    return send_file(buf, mimetype="image/jpeg")

@app.route("/make_gif", methods=["POST"])
def make_gif():
    face    = Image.open(request.files["photo"].stream).convert("RGB")
    zoom    = float(request.form.get("zoom", 1.0))
    nudge_x = int(float(request.form.get("nudge_x", 0)))
    nudge_y = int(float(request.form.get("nudge_y", 0)))
    composite = warp_face_onto(FRAMES[-1]["img"], face, zoom, nudge_x, nudge_y)
    palette_img = composite.quantize(colors=256, method=Image.Quantize.MEDIANCUT)
    out_frames = []; durations = []
    for f in FRAMES[:-1]:
        out_frames.append(f["img"].quantize(palette=palette_img, dither=0))
        durations.append(f["duration"])
    held = composite.quantize(palette=palette_img, dither=0)
    for _ in range(10):
        out_frames.append(held); durations.append(100)
    buf = io.BytesIO()
    out_frames[0].save(buf, format="GIF", save_all=True,
        append_images=out_frames[1:], duration=durations, loop=0, optimize=False)
    buf.seek(0)
    return send_file(buf, mimetype="image/gif",
                     download_name="woofmaker.gif", as_attachment=True)

if __name__ == "__main__":
    print("\n🎬 Woofmaker running at http://localhost:5000\n")
    app.run(port=5000, debug=False)
